package com.trampolim.api.education;
import java.util.*;import java.time.*;
import static com.trampolim.api.hub.HubRules.*;import static com.trampolim.api.radar.RadarModel.*;
import com.trampolim.api.radar.RadarBridge;import com.trampolim.api.future.FutureModel;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.transaction.annotation.Transactional;
@RestController
@ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class HubLearningController {
 private final JdbcTemplate jdbc;private final LearningAccess access;private final RadarBridge bridge;
 public HubLearningController(@Qualifier("capacitaJdbcTemplate")JdbcTemplate jdbc,LearningAccess access,RadarBridge bridge){this.jdbc=jdbc;this.access=access;this.bridge=bridge;}
 private String courseSelect(){return "SELECT c.id,c.title,c.description,c.category FROM learning_courses c JOIN student_users t ON t.id=c.teacher_id WHERE c.status='PUBLISHED' AND c.moderation_blocked=FALSE AND t.account_status='ACTIVE'";}
 @GetMapping("/api/public/capacita/hub/courses")public Map<String,Object> courses(@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="")String q){page(before,limit);text(q,120);return com.trampolim.api.hub.HubService.pageResult(jdbc.queryForList(courseSelect()+" AND c.id<? AND (?='' OR c.title ILIKE ?) ORDER BY c.id DESC LIMIT ?",before,q,"%"+q+"%",limit+1),limit);}
 @GetMapping("/api/public/capacita/hub/courses/{id}")public Map<String,Object> course(@PathVariable long id){return jdbc.queryForList(courseSelect()+" AND c.id=?",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Curso publicado não encontrado."));}
 @GetMapping("/api/capacita/hub/programs")public Map<String,Object> programs(@AuthenticationPrincipal String email,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit){access.account(email);page(before,limit);return bridge.convert(bridge.get("/public/hub/programs?before="+before+"&limit="+limit),Map.class);}
 @GetMapping("/api/capacita/hub/programs/{id}")public Map<String,Object> program(@AuthenticationPrincipal String email,@PathVariable long id){access.account(email);return bridge.convert(bridge.get("/public/hub/programs/"+id),Map.class);}
 @GetMapping("/api/capacita/hub/participations")public List<Map<String,Object>> participations(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT program_id,organization_id,institution_name,program_title,consent_at FROM hub_program_participations WHERE student_id=? ORDER BY program_id LIMIT 200",access.account(email).id());}
 @PutMapping("/api/capacita/hub/programs/{id}/participation")@Transactional("capacitaTransactionManager")@ResponseStatus(HttpStatus.NO_CONTENT)public void join(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Consent input){long student=access.account(email).id();if(input==null||!input.consent())bad("Confirme o compartilhamento de indicadores agregados com a instituição indicada.");var program=bridge.get("/public/hub/programs/"+id);var courseIds=new ArrayList<Long>();for(var row:program.path("courses")){long cid=row.path("course_id").asLong();course(cid);courseIds.add(cid);}com.trampolim.api.hub.HubRules.courses(courseIds);if(courseIds.isEmpty())bad("Programa sem cursos disponíveis.");jdbc.queryForObject("SELECT id FROM student_users WHERE id=? FOR UPDATE",Long.class,student);if(jdbc.queryForObject("SELECT count(*) FROM hub_program_participations WHERE student_id=?",Integer.class,student)>=200&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM hub_program_participations WHERE student_id=? AND program_id=?)",Boolean.class,student,id)))bad("Limite de participações atingido.");jdbc.update("INSERT INTO hub_program_participations(student_id,organization_id,program_id,institution_name,program_title) VALUES (?,?,?,?,?) ON CONFLICT(student_id,program_id) DO UPDATE SET institution_name=EXCLUDED.institution_name,program_title=EXCLUDED.program_title,consent_at=CURRENT_TIMESTAMP",student,program.path("organization_id").asLong(),id,text(program.path("institution_name").asText(),180),text(program.path("title").asText(),180));jdbc.update("DELETE FROM hub_participation_courses WHERE student_id=? AND program_id=?",student,id);for(Long cid:courseIds)jdbc.update("INSERT INTO hub_participation_courses(student_id,program_id,course_id) VALUES (?,?,?)",student,id,cid);jdbc.update("INSERT INTO learning_assessment_audit(actor_id,event) VALUES (?,'HUB_PROGRAM_CONSENT')",student);}
 @DeleteMapping("/api/capacita/hub/programs/{id}/participation")@ResponseStatus(HttpStatus.NO_CONTENT)public void revoke(@AuthenticationPrincipal String email,@PathVariable long id){long student=access.account(email).id();jdbc.update("DELETE FROM hub_program_participations WHERE student_id=? AND program_id=?",student,id);jdbc.update("INSERT INTO learning_assessment_audit(actor_id,event) VALUES (?,'HUB_PROGRAM_REVOKED')",student);}
 @PostMapping("/api/integrations/hub/learning")public Map<String,Object> aggregate(@RequestHeader(name="X-Trampolim-Bridge",required=false)String key,@RequestBody LearningQuery input){bridge.authorize(key);if(input==null||input.organizationId()<1||input.programs()==null||input.programs().size()>200||input.programs().stream().anyMatch(p->p==null||p.id()<1)||input.programs().stream().map(ProgramScope::id).distinct().count()!=input.programs().size())bad("Escopo inválido.");dates(input.from(),input.to());for(var p:input.programs())com.trampolim.api.hub.HubRules.courses(p.courseIds());if(input.programs().isEmpty())return Map.of("status","OK","participants",FutureModel.band(0),"courseCompletions",FutureModel.band(0));String in=String.join(",",Collections.nCopies(input.programs().size(),"?"));List<Object> participantsArgs=new ArrayList<>();participantsArgs.add(input.organizationId());input.programs().forEach(p->participantsArgs.add(p.id()));participantsArgs.add(LocalDate.parse(input.from()));participantsArgs.add(LocalDate.parse(input.to()).plusDays(1));long participants=jdbc.queryForObject("SELECT count(DISTINCT p.student_id) FROM hub_program_participations p JOIN student_users u ON u.id=p.student_id WHERE p.organization_id=? AND p.program_id IN ("+in+") AND p.consent_at>=? AND p.consent_at<? AND u.account_status='ACTIVE' AND u.email_verified=TRUE",Long.class,participantsArgs.toArray());var result=new LinkedHashMap<String,Object>();result.put("status","OK");result.put("participants",FutureModel.band(participants));if(participants<5){result.put("courseCompletions",FutureModel.band(0));return result;}
  var pairs=new ArrayList<String>();var args=new ArrayList<Object>();for(var p:input.programs())for(Long cid:p.courseIds()){pairs.add("(?::bigint,?::bigint)");args.add(p.id());args.add(cid);}if(pairs.isEmpty()){result.put("courseCompletions",FutureModel.band(0));return result;}args.add(input.organizationId());args.add(LocalDate.parse(input.from()));args.add(LocalDate.parse(input.to()).plusDays(1));
  // Same completion rule as the learning dashboard: published ready lessons (at least one), all completed, all required assessments passed.
  String sql="WITH allowed(program_id,course_id) AS (VALUES "+String.join(",",pairs)+"), cohort AS (SELECT DISTINCT p.student_id,a.course_id FROM hub_program_participations p JOIN hub_participation_courses k ON k.student_id=p.student_id AND k.program_id=p.program_id JOIN allowed a ON a.program_id=p.program_id AND a.course_id=k.course_id JOIN student_users u ON u.id=p.student_id AND u.account_status='ACTIVE' AND u.email_verified=TRUE JOIN learning_courses c ON c.id=a.course_id AND c.status='PUBLISHED' AND c.moderation_blocked=FALSE JOIN student_users t ON t.id=c.teacher_id AND t.account_status='ACTIVE' WHERE p.organization_id=? AND p.consent_at>=? AND p.consent_at<?), lessons AS (SELECT h.student_id,h.course_id,count(l.id) AS total,count(p.completed_at) AS completed FROM cohort h JOIN learning_subjects s ON s.course_id=h.course_id JOIN learning_modules m ON m.subject_id=s.id JOIN learning_lessons l ON l.module_id=m.id AND l.status='PUBLISHED' AND l.validation_status='READY' LEFT JOIN learning_lesson_progress p ON p.student_id=h.student_id AND p.lesson_id=l.id GROUP BY h.student_id,h.course_id), done AS (SELECT l.student_id,l.course_id FROM lessons l WHERE l.total>0 AND l.total=l.completed AND NOT EXISTS(SELECT 1 FROM learning_assessments a JOIN learning_assessment_versions v ON v.id=a.current_version_id WHERE a.course_id=l.course_id AND a.status='PUBLISHED' AND (v.definition->>'requiredForCompletion')::boolean=TRUE AND NOT EXISTS(SELECT 1 FROM learning_assessment_attempts t WHERE t.student_id=l.student_id AND t.assessment_id=a.id AND t.passed=TRUE))) SELECT count(*) AS completions,count(DISTINCT student_id) AS contributors FROM done";var counts=jdbc.queryForMap(sql,args.toArray());long contributors=((Number)counts.get("contributors")).longValue();result.put("courseCompletions",contributors<5?FutureModel.band(0):FutureModel.band(((Number)counts.get("completions")).longValue()));result.put("completionContributors",FutureModel.band(contributors));result.put("notice","Coorte de adesão autorizada no período, situação atual das conclusões. Não inclui cursos adicionados depois do consentimento sem nova autorização. Não emite certificados nem expõe dados individuais.");return result;
 }
}
